import requests, json, sys
URL="http://loophole-sim:8000/mcp"
class MCP:
    def __init__(self,url=URL):
        self.url=url
        self.s=requests.Session()
        self.id=0
        self.ep=None
        self.init()
    def _post(self,payload,headers=None):
        h={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}
        if headers: h.update(headers)
        r=self.s.post(self.url,json=payload,headers=h,timeout=60)
        return r
    def _parse(self,r):
        ct=r.headers.get("content-type","")
        if "text/event-stream" in ct:
            # parse SSE
            data_lines=[]
            for line in r.text.splitlines():
                if line.startswith("data:"):
                    data_lines.append(line[5:].strip())
            if not data_lines: return None
            return json.loads(data_lines[-1])
        else:
            return r.json()
    def init(self):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"py","version":"1"}}}
        r=self._post(payload)
        self.ep=r.headers.get("mcp-session-id")
        resp=self._parse(r)
        # send initialized notification
        self.s.post(self.url,json={"jsonrpc":"2.0","method":"notifications/initialized"},headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream","mcp-session-id":self.ep},timeout=10)
        return resp
    def call(self,name,args=None):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"tools/call","params":{"name":name,"arguments":args or {}}}
        h={"mcp-session-id":self.ep} if self.ep else {}
        r=self._post(payload,h)
        return self._parse(r)
    def tools(self):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"tools/list","params":{}}
        h={"mcp-session-id":self.ep} if self.ep else {}
        return self._parse(self._post(payload,h))
if __name__=="__main__":
    m=MCP()
    import pprint
    pprint.pprint(m.tools())
