import json, urllib.request, urllib.error
URL="http://loophole-sim:8000/mcp"
class MCP:
    def __init__(self,url=URL):
        self.url=url
        self.id=0
        self.ep=None
        self.init()
    def _post(self,payload,extra=None):
        data=json.dumps(payload).encode()
        headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}
        if extra: headers.update(extra)
        req=urllib.request.Request(self.url,data=data,headers=headers,method="POST")
        try:
            resp=urllib.request.urlopen(req,timeout=60)
            return resp.status, dict(resp.headers), resp.read().decode()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read().decode()
    def _parse(self,status,headers,body):
        ct=headers.get("Content-Type","") or headers.get("content-type","")
        if "text/event-stream" in ct:
            dl=[l[5:].strip() for l in body.splitlines() if l.startswith("data:")]
            if not dl: return None
            return json.loads(dl[-1])
        return json.loads(body) if body.strip() else None
    def init(self):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"py","version":"1"}}}
        st,h,b=self._post(payload)
        self.ep=h.get("mcp-session-id") or h.get("Mcp-Session-Id")
        resp=self._parse(st,h,b)
        extra={"mcp-session-id":self.ep} if self.ep else {}
        req=urllib.request.Request(self.url,data=json.dumps({"jsonrpc":"2.0","method":"notifications/initialized"}).encode(),headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream",**extra},method="POST")
        try: urllib.request.urlopen(req,timeout=10)
        except: pass
        return resp
    def call(self,name,args=None):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"tools/call","params":{"name":name,"arguments":args or {}}}
        extra={"mcp-session-id":self.ep} if self.ep else {}
        st,h,b=self._post(payload,extra)
        return self._parse(st,h,b)
    def tools(self):
        self.id+=1
        payload={"jsonrpc":"2.0","id":self.id,"method":"tools/list","params":{}}
        extra={"mcp-session-id":self.ep} if self.ep else {}
        st,h,b=self._post(payload,extra)
        return self._parse(st,h,b)
if __name__=="__main__":
    m=MCP()
    print("session",m.ep)
    t=m.tools()
    print(json.dumps(t,indent=1)[:2000])
